use super::*;

const CADENCE_DAYS: [(IncomeCadence, i64, i64); 4] = [
    (IncomeCadence::Weekly, 7, 2),
    (IncomeCadence::Biweekly, 14, 3),
    // Twice a month (the 1st and 15th) averages ~15.2 days and is NOT biweekly — 24 payments a year
    // against 26. Treating one as the other misstates annual income by two whole payments.
    (IncomeCadence::Semimonthly, 15, 2),
    (IncomeCadence::Monthly, 30, 5),
];

/// Which rhythm the gaps describe.
///
/// # Semimonthly against biweekly, and why a median cannot decide it
///
/// Getting this wrong costs two whole payments a year — 24 against 26 — which is a month and a half
/// of rent hidden inside the arithmetic. Paid on the 1st and 15th, the gaps ALTERNATE 14 and 16-17,
/// whose median lands exactly where biweekly lives. Paid every fortnight, the gaps are CONSTANT at
/// 14. That constancy is the discriminator, so it is what this checks rather than the average.
pub fn classify_cadence(gaps: &[i64]) -> IncomeCadence {
    if gaps.is_empty() {
        return IncomeCadence::Irregular;
    }
    let typical = median(gaps);
    if (13..=17).contains(&typical) {
        let hi = gaps.iter().max().copied().unwrap_or(0);
        let lo = gaps.iter().min().copied().unwrap_or(0);
        return if hi - lo >= 2 { IncomeCadence::Semimonthly } else { IncomeCadence::Biweekly };
    }
    CADENCE_DAYS
        .iter()
        .find(|(_, days, tol)| (typical - days).abs() <= *tol)
        .map(|(c, _, _)| *c)
        .unwrap_or(IncomeCadence::Irregular)
}
